import{_ as s,o as n,c as t,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const h=JSON.parse('{"title":"第 9 章 写文档：报告、方案与白皮书","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 9 章 写文档：报告、方案与白皮书.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 9 章 写文档：报告、方案与白皮书.md"}'),l={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 9 章 写文档：报告、方案与白皮书.md"};function i(o,a,p,r,c,d){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="第-9-章-写文档-报告、方案与白皮书" tabindex="-1">第 9 章 写文档：报告、方案与白皮书 <a class="header-anchor" href="#第-9-章-写文档-报告、方案与白皮书" aria-label="Permalink to &quot;第 9 章 写文档：报告、方案与白皮书&quot;">​</a></h1><h2 id="_9-1-场景" tabindex="-1">9.1 场景 <a class="header-anchor" href="#_9-1-场景" aria-label="Permalink to &quot;9.1 场景&quot;">​</a></h2><p>写文档是最高频的 AI 任务，但也最容易&quot;看着像、其实没用&quot;。本章以三个典型场景为例：</p><ul><li><strong>报告</strong>：运营/项目/周报，基于数据说话；</li><li><strong>方案</strong>：需求文档、技术方案、立项书；</li><li><strong>长文档</strong>：白皮书、手册、教程（比如你现在读的这本）。</li></ul><h2 id="_9-2-通用流程" tabindex="-1">9.2 通用流程 <a class="header-anchor" href="#_9-2-通用流程" aria-label="Permalink to &quot;9.2 通用流程&quot;">​</a></h2><p>无论写哪种文档，都走这个流程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 明确读者与用途（给谁看、看完要做什么决定）</span></span>
<span class="line"><span>2. 收集素材（数据、资料、模板）</span></span>
<span class="line"><span>3. 搭结构（大纲先行，你确认）</span></span>
<span class="line"><span>4. 分块写作（每块可检查）</span></span>
<span class="line"><span>5. 数据/事实核对（我能查的帮你查）</span></span>
<span class="line"><span>6. 按你的风格润色</span></span></code></pre></div><p><strong>关键动作：先出大纲再动笔。</strong> 大纲错了，写一万字也白搭；大纲对了，填充只是时间问题。</p><h2 id="_9-3-案例-一份基于数据的运营报告" tabindex="-1">9.3 案例：一份基于数据的运营报告 <a class="header-anchor" href="#_9-3-案例-一份基于数据的运营报告" aria-label="Permalink to &quot;9.3 案例：一份基于数据的运营报告&quot;">​</a></h2><p><strong>指令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写一份《Q3 运营复盘报告》：</span></span>
<span class="line"><span>- 数据源：data/q3.csv（阅读后使用，不得编造）</span></span>
<span class="line"><span>- 读者：管理层，结论先行</span></span>
<span class="line"><span>- 结构：核心结论 → 分渠道表现 → 问题分析 → 3 条建议</span></span>
<span class="line"><span>- 长度：不超过 3 页</span></span></code></pre></div><p><strong>我的做法：</strong></p><ol><li>Read 数据文件，先搞清字段和口径（必要时问你）；</li><li>给出大纲：&quot;结论 → 渠道对比 → 问题 → 建议&quot;，你确认；</li><li>逐节写作，结论带数据引用（&quot;渠道 A 环比下降 18%，见 2.1 节&quot;）；</li><li>交付后附&quot;数据来源与口径说明&quot;，方便你核验。</li></ol><p><strong>复盘与复用：</strong></p><ul><li>把&quot;先大纲后正文 + 结论先行 + 数据可核验&quot;存成你的文档偏好（记忆）；</li><li>把指令模板存下来，下次换文件名即可复用。</li></ul><h2 id="_9-4-案例-一份方案文档" tabindex="-1">9.4 案例：一份方案文档 <a class="header-anchor" href="#_9-4-案例-一份方案文档" aria-label="Permalink to &quot;9.4 案例：一份方案文档&quot;">​</a></h2><p>写方案的关键是<strong>决策支持</strong>：读者看完要能拍板。结构建议：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>背景与目标 → 现状分析 → 方案选项（A/B/C 对比）→ 推荐项与理由 → 实施计划 → 风险与对策</span></span></code></pre></div><p><strong>指令要点：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写《XX 系统改造方案》：给出 3 个方案并对比（成本/工期/风险），</span></span>
<span class="line"><span>推荐一个并说明理由，最后附实施步骤和验收标准。</span></span></code></pre></div><h2 id="_9-5-文档写作的红线" tabindex="-1">9.5 文档写作的红线 <a class="header-anchor" href="#_9-5-文档写作的红线" aria-label="Permalink to &quot;9.5 文档写作的红线&quot;">​</a></h2><ul><li>❌ <strong>不编数据</strong>：数据要么来自你给的文件，要么明确标注&quot;待核实&quot;；</li><li>❌ 不隐瞒不确定性：拿不准的地方写&quot;建议核实&quot;；</li><li>✅ 保留修订痕迹：用 Edit 逐轮改，而不是整篇重写，方便你 review diff；</li><li>✅ 结构可复用：好文档 = 好模板 + 好内容，模板沉淀下来。</li></ul><h2 id="_9-6-练习" tabindex="-1">9.6 练习 <a class="header-anchor" href="#_9-6-练习" aria-label="Permalink to &quot;9.6 练习&quot;">​</a></h2><ol><li>给我一份真实数据文件，让我写一份带结论的报告（先看大纲）。</li><li>让我按你公司的格式（如果有模板）重写一次。</li><li>把这份文档的指令模板存入记忆。</li></ol><blockquote><p>小结：AI 写文档的价值不在&quot;代笔&quot;，而在<strong>把写作变成可管理、可核验、可复用的流程</strong>。</p></blockquote>`,25)])])}const _=s(l,[["render",i]]);export{h as __pageData,_ as default};
